import{_ as t,o as e,c as p,a3 as n,j as a}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"01 · 索引与 B+ 树","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/db/01.md","filePath":"bagu/db/01.md"}'),l={name:"bagu/db/01.md"};function o(i,s,r,c,d,h){return e(),p("div",null,[...s[0]||(s[0]=[n(`<h1 id="_01-·-索引与-b-树" tabindex="-1">01 · 索引与 B+ 树 <a class="header-anchor" href="#_01-·-索引与-b-树" aria-label="Permalink to &quot;01 · 索引与 B+ 树&quot;">​</a></h1><blockquote><p>数据库最核心的一篇。<strong>懂了这篇，80% 的 SQL 优化题都能推出来。</strong></p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>索引是<strong>为了减少磁盘 IO 次数而额外维护的一份有序结构</strong>——用&quot;多占空间 + 写变慢&quot;，换&quot;读变快&quot;。</p><h2 id="生活类比-图书馆的索引柜" tabindex="-1">生活类比：图书馆的索引柜 <a class="header-anchor" href="#生活类比-图书馆的索引柜" aria-label="Permalink to &quot;生活类比：图书馆的索引柜&quot;">​</a></h2><p><strong>没有索引</strong>：你要找&quot;作者是余华的书&quot;，只能从第一个书架翻到最后一个。100 万本书，翻到天黑。</p><p><strong>有索引</strong>：索引柜里有一叠卡片，按作者名排好序，每张卡片写着&quot;余华 → 3 排 2 号架&quot;。</p><ul><li>找&quot;余华&quot;：直接在卡片里二分，几秒定位 → <strong>快</strong></li><li>但每次进新书，都要<strong>多做一张卡片</strong> → <strong>写变慢</strong></li><li>卡片柜本身占地方 → <strong>多占空间</strong></li></ul><p><strong>这就是索引的全部本质</strong>。所有细节都是这句话的展开。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、为什么是-b-树-把三个候选都比一遍" tabindex="-1">一、为什么是 B+ 树（把三个候选都比一遍） <a class="header-anchor" href="#一、为什么是-b-树-把三个候选都比一遍" aria-label="Permalink to &quot;一、为什么是 B+ 树（把三个候选都比一遍）&quot;">​</a></h3><p><strong>核心约束：磁盘 IO 次数 = 树高</strong>。一次 IO 约 10ms（机械盘），必须把树高压到最低。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>候选 1：哈希表</span></span>
<span class="line"><span>  ✅ 等值查询 O(1)</span></span>
<span class="line"><span>  ❌ 不支持范围查询（age &gt; 20 得全扫）</span></span>
<span class="line"><span>  ❌ 不支持排序</span></span>
<span class="line"><span>  ❌ 不支持最左前缀</span></span>
<span class="line"><span>  &gt; 淘汰（只能做辅助索引）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>候选 2：红黑树（二叉）</span></span>
<span class="line"><span>  1000 万行 &gt; 树高 ≈ log₂(1000万) ≈ 24 层</span></span>
<span class="line"><span>  &gt; 24 次磁盘 IO × 10ms = 240ms</span></span>
<span class="line"><span>  &gt; 淘汰</span></span>
<span class="line"><span></span></span>
<span class="line"><span>候选 3：B 树（多叉）</span></span>
<span class="line"><span>  一个节点存几百个键 &gt; 树高 3~4 层</span></span>
<span class="line"><span>  ✅ 树高低</span></span>
<span class="line"><span>  ❌ 数据存在所有节点上（包括非叶子），一个节点能存的键变少</span></span>
<span class="line"><span>  ❌ 范围查询要在树上反复上下跳</span></span>
<span class="line"><span></span></span>
<span class="line"><span>候选 4：B+ 树</span></span>
<span class="line"><span>  ✅ 数据只在叶子节点，非叶子只存索引 &gt; 一个节点能存更多键 &gt; 树高更低</span></span>
<span class="line"><span>  ✅ 叶子节点用双向链表串起来 &gt; 范围查询直接顺序扫，不用回到根</span></span>
<span class="line"><span>  ✅ 每次查询都要走到叶子 &gt; IO 次数稳定（B 树可能提前命中，也可能不）</span></span>
<span class="line"><span>  &gt; 胜出</span></span></code></pre></div><h3 id="二、b-树的结构-innodb-页大小-16kb" tabindex="-1">二、B+ 树的结构（InnoDB，页大小 16KB） <a class="header-anchor" href="#二、b-树的结构-innodb-页大小-16kb" aria-label="Permalink to &quot;二、B+ 树的结构（InnoDB，页大小 16KB）&quot;">​</a></h3>`,14),a("figure",{class:"fig"},[a("span",{class:"fig-hint"},"← 左右滑动看完整图 →"),a("svg",{viewBox:"0 0 680 290",width:"100%",xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"B+ 树三层结构示意图"},[a("defs",null,[a("marker",{id:"arw-bpt",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto-start-reverse"},[a("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})]),a("marker",{id:"arw-bpt-hi",viewBox:"0 0 10 10",markerWidth:"9",markerHeight:"9",refX:"8.5",refY:"5",markerUnits:"userSpaceOnUse",orient:"auto-start-reverse"},[a("path",{d:"M2 1.5 L8 5 L2 8.5",class:"f-line-hi",fill:"none","stroke-linecap":"round","stroke-linejoin":"round"})])]),a("path",{class:"f-line",d:"M405 52 V78 H230 V110","marker-end":"url(#arw-bpt)"}),a("path",{class:"f-line",d:"M405 52 V110","marker-end":"url(#arw-bpt)"}),a("path",{class:"f-line",d:"M405 52 V78 H580 V110","marker-end":"url(#arw-bpt)"}),a("rect",{class:"f-box-alt",x:"315",y:"8",width:"180",height:"44",rx:"8"}),a("text",{class:"f-mono",x:"405",y:"36","text-anchor":"middle"},"[ 10 | 30 ]"),a("rect",{class:"f-box",x:"170",y:"110",width:"120",height:"44",rx:"8"}),a("text",{class:"f-mono",x:"230",y:"138","text-anchor":"middle"},"[ 1 | 5 ]"),a("rect",{class:"f-box",x:"345",y:"110",width:"120",height:"44",rx:"8"}),a("text",{class:"f-mono",x:"405",y:"138","text-anchor":"middle"},"[ 10 | 20 ]"),a("rect",{class:"f-box",x:"520",y:"110",width:"120",height:"44",rx:"8"}),a("text",{class:"f-mono",x:"580",y:"138","text-anchor":"middle"},"[ 30 | 50 ]"),a("path",{class:"f-line",d:"M230 154 V206","marker-end":"url(#arw-bpt)"}),a("path",{class:"f-line",d:"M405 154 V206","marker-end":"url(#arw-bpt)"}),a("path",{class:"f-line",d:"M580 154 V206","marker-end":"url(#arw-bpt)"}),a("rect",{class:"f-box-hi",x:"170",y:"206",width:"120",height:"46",rx:"8"}),a("text",{class:"f-mono",x:"230",y:"235","text-anchor":"middle"},"key=1 整行"),a("rect",{class:"f-box-hi",x:"345",y:"206",width:"120",height:"46",rx:"8"}),a("text",{class:"f-mono",x:"405",y:"235","text-anchor":"middle"},"key=10 整行"),a("rect",{class:"f-box-hi",x:"520",y:"206",width:"120",height:"46",rx:"8"}),a("text",{class:"f-mono",x:"580",y:"235","text-anchor":"middle"},"key=30 整行"),a("path",{class:"f-line-hi",d:"M290 229 H345","marker-start":"url(#arw-bpt-hi)","marker-end":"url(#arw-bpt-hi)"}),a("path",{class:"f-line-hi",d:"M465 229 H520","marker-start":"url(#arw-bpt-hi)","marker-end":"url(#arw-bpt-hi)"}),a("text",{class:"f-label",x:"10",y:"34"},"根：键 + 子指针"),a("text",{class:"f-label",x:"10",y:"136"},"分支：键 + 子指针"),a("text",{class:"f-label",x:"10",y:"233"},"叶子：整行数据"),a("text",{class:"f-label",x:"240",y:"184"},"< 10"),a("text",{class:"f-label",x:"415",y:"184"},"10 ~ 29"),a("text",{class:"f-label",x:"590",y:"184"},"≥ 30"),a("text",{class:"f-label",x:"405",y:"276","text-anchor":"middle"},"叶子之间是双向链表 → 范围查询顺着链表扫，不用回到根")]),a("figcaption",{class:"fig-cap"},"非叶子节点只存「键 + 子指针」，一页能塞下上千个键，所以 2000 万行的表树高也只有 3 层；数据全在叶子，叶子之间用双向链表串起来——范围查询顺着链表扫，不用回到根。")],-1),n(`<p>一个节点就是一页（16KB）。根和分支只存「键 + 子节点指针」，一页能放约 1170 个键，所以树很矮；真正存整行数据的只有叶子，叶子之间用双向链表相连，范围查询顺着链表扫就行，不用回到根。</p><p><strong>树高能压到多低</strong>（算一下，面试常问）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>假设：</span></span>
<span class="line"><span>  页大小 16KB</span></span>
<span class="line"><span>  主键 bigint（8 字节）+ 页指针（6 字节）= 14 字节</span></span>
<span class="line"><span>  一个非叶子节点能存：16KB / 14B ≈ 1170 个键</span></span>
<span class="line"><span>  一行数据约 1KB &gt; 一个叶子节点能存约 16 行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三层 B+ 树能存多少行？</span></span>
<span class="line"><span>  第 1 层（根）：1 个节点</span></span>
<span class="line"><span>  第 2 层：1170 个节点</span></span>
<span class="line"><span>  第 3 层（叶子）：1170 × 1170 ≈ 137 万个节点</span></span>
<span class="line"><span>  总行数：137 万 × 16 ≈ 2200 万行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>结论：2000 万行的表，树高只有 3 层 &gt; 3 次 IO</span></span></code></pre></div><p><strong>这就是 B+ 树的核心价值</strong>：把 24 次 IO 压到 3 次。</p><h3 id="三、聚簇索引-vs-二级索引-必考" tabindex="-1">三、聚簇索引 vs 二级索引（必考） <a class="header-anchor" href="#三、聚簇索引-vs-二级索引-必考" aria-label="Permalink to &quot;三、聚簇索引 vs 二级索引（必考）&quot;">​</a></h3><p><strong>聚簇索引（主键索引）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>叶子节点直接存&quot;整行数据&quot;</span></span>
<span class="line"><span>  [主键=1 | 整行数据] &gt; [主键=2 | 整行数据] &gt; ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一张表只有一个聚簇索引（因为数据只能按一种方式物理组织）</span></span></code></pre></div><p><strong>二级索引（辅助索引）</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>叶子节点存&quot;索引列 + 主键值&quot;</span></span>
<span class="line"><span>  [name=&#39;张三&#39; | 主键=5] &gt; [name=&#39;李四&#39; | 主键=8] &gt; ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可以有多个</span></span></code></pre></div><p><strong>回表</strong>：用二级索引查到主键值后，<strong>还要再去聚簇索引查一次完整数据</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM user WHERE name = &#39;张三&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>① 走 name 索引，找到 name=&#39;张三&#39; 的记录，拿到主键 id=5</span></span>
<span class="line"><span>② 拿 id=5 去聚簇索引查，拿到整行</span></span>
<span class="line"><span>&gt; 两次 B+ 树查找 = 两次（可能更多）IO</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这就是&quot;回表&quot;，也是&quot;为什么 SELECT * 比 SELECT 具体列慢&quot;的原因之一</span></span></code></pre></div><p><strong>覆盖索引</strong>：如果查询的列<strong>全都在索引里</strong>，就不用回表。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>索引 (name, age)</span></span>
<span class="line"><span>SELECT name, age FROM user WHERE name = &#39;张三&#39;;</span></span>
<span class="line"><span>&gt; name 和 age 都在索引里，直接返回，不回表 ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SELECT name, age, email FROM user WHERE name = &#39;张三&#39;;</span></span>
<span class="line"><span>&gt; email 不在索引里，必须回表 ❌</span></span></code></pre></div><p><strong>这是最重要的优化手段之一</strong>：把常用查询的列做成联合索引，实现&quot;索引覆盖&quot;。</p><h3 id="四、最左前缀原则" tabindex="-1">四、最左前缀原则 <a class="header-anchor" href="#四、最左前缀原则" aria-label="Permalink to &quot;四、最左前缀原则&quot;">​</a></h3><p>联合索引 <code>(a, b, c)</code> 的排序方式是：<strong>先按 a 排，a 相同再按 b 排，b 相同再按 c 排</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>索引里的顺序：</span></span>
<span class="line"><span>(1,1,1) (1,1,2) (1,2,1) (1,2,2) (2,1,1) (2,1,2) ...</span></span>
<span class="line"><span> ^a    ^b    ^c</span></span></code></pre></div><p>所以能用的查询：</p><table tabindex="0"><thead><tr><th>查询条件</th><th>能用索引吗</th><th>用到几列</th></tr></thead><tbody><tr><td><code>a=1</code></td><td>✅</td><td>a</td></tr><tr><td><code>a=1 AND b=2</code></td><td>✅</td><td>a, b</td></tr><tr><td><code>a=1 AND b=2 AND c=3</code></td><td>✅</td><td>a, b, c</td></tr><tr><td><code>b=2</code></td><td>❌</td><td>完全用不了（不知道 a 就没法定位）</td></tr><tr><td><code>a=1 AND c=3</code></td><td>⚠️</td><td>只用 a，c 用不上（b 断了）</td></tr><tr><td><code>a&gt;1 AND b=2</code></td><td>⚠️</td><td>只用 a（范围查询后面的列失效）</td></tr></tbody></table><p>**&quot;范围查询后面的列失效&quot;**是高频考点：因为 <code>a &gt; 1</code> 之后，a 有多个值，b 在每个 a 内部有序但整体无序，无法再用 b 做定位。</p><p><strong>例外</strong>：MySQL 5.6+ 的&quot;索引下推&quot;（ICP）可以在索引上过滤 b，减少回表次数，但仍不能用于定位。</p><h3 id="五、索引失效的常见原因" tabindex="-1">五、索引失效的常见原因 <a class="header-anchor" href="#五、索引失效的常见原因" aria-label="Permalink to &quot;五、索引失效的常见原因&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 对索引列做函数/运算</span></span>
<span class="line"><span>   WHERE YEAR(create_time) = 2026     ❌</span></span>
<span class="line"><span>   WHERE create_time &gt;= &#39;2026-01-01&#39;  ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 隐式类型转换</span></span>
<span class="line"><span>   索引是 varchar，却写 WHERE phone = 13800138000（数字）  ❌</span></span>
<span class="line"><span>   &gt; 数据库会把每行的 phone 转成数字比较，等于对列做函数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 前导模糊匹配</span></span>
<span class="line"><span>   WHERE name LIKE &#39;%三&#39;   ❌（无法二分，因为不知道从哪开始）</span></span>
<span class="line"><span>   WHERE name LIKE &#39;张%&#39;   ✅</span></span>
<span class="line"><span></span></span>
<span class="line"><span>④ OR 连接的列没有都建索引</span></span>
<span class="line"><span>   WHERE a=1 OR b=2  &gt; 如果 b 没索引，全表扫</span></span>
<span class="line"><span></span></span>
<span class="line"><span>⑤ 区分度太低</span></span>
<span class="line"><span>   性别字段只有 2 个值 &gt; 索引扫描的行数接近全表，优化器会放弃索引</span></span>
<span class="line"><span></span></span>
<span class="line"><span>⑥ 使用了 != 、NOT IN、IS NOT NULL（部分情况）</span></span>
<span class="line"><span>   &gt; 因为要扫描的行太多，优化器判断不如全表扫</span></span></code></pre></div><h3 id="六、什么时候不该建索引" tabindex="-1">六、什么时候不该建索引 <a class="header-anchor" href="#六、什么时候不该建索引" aria-label="Permalink to &quot;六、什么时候不该建索引&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 表很小（几百行）&gt; 全表扫更快</span></span>
<span class="line"><span>② 写多读少 &gt; 每次写都要维护索引</span></span>
<span class="line"><span>③ 区分度极低 &gt; 索引用不上</span></span>
<span class="line"><span>④ 频繁更新的列 &gt; 索引维护成本高</span></span>
<span class="line"><span>⑤ 已经有更合适的联合索引（避免冗余索引）</span></span></code></pre></div><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果页大小是-4kb-而不是-16kb" tabindex="-1">反事实 1：如果页大小是 4KB 而不是 16KB <a class="header-anchor" href="#反事实-1-如果页大小是-4kb-而不是-16kb" aria-label="Permalink to &quot;反事实 1：如果页大小是 4KB 而不是 16KB&quot;">​</a></h3><p>一个节点能存的键少了 4 倍，树高增加。按上面的计算，2000 万行可能要 4 层而不是 3 层——多一次 IO，性能下降 30%+。</p><p><strong>16KB 是权衡</strong>：太小树高增加，太大一次 IO 读的数据用不完（浪费带宽）、且 Buffer Pool 管理粒度变粗。</p><h3 id="反事实-2-如果数据也存在非叶子节点-b-树" tabindex="-1">反事实 2：如果数据也存在非叶子节点（B 树） <a class="header-anchor" href="#反事实-2-如果数据也存在非叶子节点-b-树" aria-label="Permalink to &quot;反事实 2：如果数据也存在非叶子节点（B 树）&quot;">​</a></h3><p>一个非叶子节点原本能存 1170 个键，现在要存&quot;键 + 数据&quot;，假设数据 1KB，那一个节点只能存 16 个键——树高会暴增。</p><p><strong>B+ 树把数据全部下沉到叶子，正是为了让非叶子节点&quot;尽可能多地存键&quot;</strong>，从而压低树高。</p><h3 id="反事实-3-如果没有索引" tabindex="-1">反事实 3：如果没有索引 <a class="header-anchor" href="#反事实-3-如果没有索引" aria-label="Permalink to &quot;反事实 3：如果没有索引&quot;">​</a></h3><p>1000 万行的表，<code>WHERE id = 123</code> 要全表扫描：读 1000 万行 × 1KB = 10GB 数据。即使顺序读，也要几秒到几十秒。</p><p>有了索引：3 次 IO，约 30ms。<strong>差了 1000 倍</strong>。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：为什么用 B+ 树而不是 B 树？</strong></p><blockquote><p>三点：① 数据只在叶子 &gt; 非叶子能存更多键 &gt; 树高更低；② 叶子有链表 &gt; 范围查询直接顺序扫；③ 每次查询都到叶子 &gt; IO 次数稳定可预测。</p></blockquote><p><strong>Q：为什么不用红黑树/哈希？</strong></p><blockquote><p>红黑树树高太高（24 层 = 24 次 IO）；哈希不支持范围查询、排序、最左前缀。</p></blockquote><p><strong>Q：什么是回表？怎么避免？</strong></p><blockquote><p>二级索引叶子只存主键，查其他列要再回聚簇索引查一次。避免方式：<strong>覆盖索引</strong>（把要查的列都放进索引）。</p></blockquote><p><strong>Q：什么是聚簇索引？</strong></p><blockquote><p>叶子节点存整行数据的索引。一张表只有一个（通常是主键）。InnoDB 必须有聚簇索引——没主键就用唯一非空索引，再没有就生成隐藏的 row_id。</p></blockquote><p><strong>Q：联合索引的最左前缀原则？</strong></p><blockquote><p>索引按 (a,b,c) 顺序排列，所以必须从 a 开始用。跳过 a 直接用 b 用不了；a 用了范围查询后，b、c 只能用于过滤（索引下推），不能用于定位。</p></blockquote><p><strong>Q：索引越多越好吗？</strong></p><blockquote><p>不是。每个索引都要占空间，且每次 INSERT/UPDATE/DELETE 都要维护所有索引。写多的表，索引会显著拖慢写入。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>索引为什么快？</span></span>
<span class="line"><span>  &gt; 因为减少了磁盘 IO</span></span>
<span class="line"><span>    &gt; 为什么 B+ 树 IO 少？（树高低，3 层）</span></span>
<span class="line"><span>      &gt; 为什么树高低？（多叉 + 数据只在叶子）</span></span>
<span class="line"><span>        &gt; 为什么不用 B 树？（数据占空间，节点存键少）</span></span>
<span class="line"><span>          &gt; 为什么不用哈希？（不支持范围）</span></span>
<span class="line"><span>            &gt; 二级索引查到主键后还要做什么？（回表）</span></span>
<span class="line"><span>              &gt; 怎么避免回表？（覆盖索引）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/dsa/03">树与堆</a>：B+ 树是多叉平衡树 + 叶子链表</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/dsa/01">复杂度与数组、链表</a>：叶子链表让范围查询变成&quot;顺序扫描&quot;，这是链表特性</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：页大小 16KB、Buffer Pool 缓存页，和虚拟内存的&quot;页&quot;是同一个思路</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/02">事务与 ACID</a>：写操作要更新索引，索引页的修改也要写 redo log</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/04">锁与死锁</a>：索引决定了加锁的范围（没走索引 &gt; 锁全表）</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/05">SQL 执行与优化</a>：优化器的核心工作就是&quot;选哪个索引&quot;</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：2000 万行的表，为什么 B+ 树只有 3 层？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>按 16KB 页算：</p><ul><li>非叶子节点：每个键 + 指针约 14 字节 &gt; 一页能放 <code>16384/14 ≈ 1170</code> 个键。</li><li>叶子节点：一行约 1KB &gt; 一页能放约 16 行。</li></ul><p>三层结构：</p><ul><li>第 1 层（根）：1 个节点，1170 个分支</li><li>第 2 层：1170 个节点，共 <code>1170 × 1170 ≈ 137 万</code> 个分支</li><li>第 3 层（叶子）：137 万个叶子节点 × 16 行 ≈ <strong>2200 万行</strong></li></ul><p>所以 2000 万行确实只要 3 层，<strong>查任意一行最多 3 次 IO</strong>。</p><p>注意：这是&quot;主键 bigint + 行 1KB&quot;的估算。行越大、主键越长，能存的行数越少。</p></details><p><strong>Q2：为什么 <code>WHERE a &gt; 1 AND b = 2</code> 用不上联合索引 <code>(a,b)</code> 的 b？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为索引的排序是&quot;<strong>先按 a，再按 b</strong>&quot;。</p><p><code>a &gt; 1</code> 会命中多个 a 值（比如 a=2,3,4...）。在每个 a 内部，b 是有序的；但<strong>跨 a 的时候，b 整体无序</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a=2: b=1,2,3</span></span>
<span class="line"><span>a=3: b=1,2,3</span></span></code></pre></div><p>要找&quot;b=2&quot;，在 a=2 里有一个，a=3 里有一个，a=4 里还有一个……<strong>必须把每个 a 都扫一遍</strong>，无法像等值查询那样一次定位。</p><p>所以 b 只能用于&quot;过滤&quot;（索引下推，减少回表），不能用于&quot;定位&quot;（缩小扫描范围）。</p><p><strong>对比</strong>：<code>a = 1 AND b = 2</code> 能精确定位到唯一位置，因为 a 是等值，b 在 a=1 内部有序。</p></details><p><strong>Q3：为什么 <code>WHERE phone = 13800138000</code> 会让 varchar 索引失效？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为<strong>隐式类型转换</strong>。</p><p>MySQL 在比较 varchar 和数字时，会把<strong>字符串转成数字</strong>（而不是把数字转成字符串）。这个转换作用在<strong>每一行</strong>上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>等价于：WHERE CAST(phone AS SIGNED) = 13800138000</span></span></code></pre></div><p>一旦对索引列用了函数，B+ 树的有序性就被破坏了——数据库不知道 <code>CAST(phone)</code> 的结果在索引里是什么顺序，只能全表扫描。</p><p><strong>正确写法</strong>：<code>WHERE phone = &#39;13800138000&#39;</code>（加引号）。</p><p>这个坑非常常见，因为很多 ORM 或前端传参时类型不对，表面看不出来。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;卡片柜&quot;类比会让人以为索引和数据是两份独立的拷贝</strong>。聚簇索引的叶子<strong>就是数据本身</strong>，只有二级索引才是&quot;另存一份&quot;。</li><li><strong>&quot;索引让查询变快&quot;不绝对</strong>。区分度低（如性别）或要返回大量行时，优化器会主动放弃索引——<strong>全表扫可能更快</strong>。</li><li><strong>B+ 树的&quot;+&quot;不是&quot;加强版&quot;的意思</strong>，是指&quot;数据都在叶子层&quot;这个结构差异。</li><li><strong>不是所有引擎都有聚簇索引</strong>。MyISAM 的索引和数据完全分离（叶子存的是数据地址），所以它没有聚簇索引。</li><li><strong>索引下推（ICP）不是&quot;能用于定位&quot;</strong>。它只是把过滤条件下推到索引层，减少回表次数，不改变&quot;范围查询后列失效&quot;这个事实。</li><li><strong><code>LIKE &#39;张%&#39;</code> 能用索引，<code>LIKE &#39;%张&#39;</code> 不能</strong>——因为前者知道从哪开始找，后者不知道。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能算出&quot;2000 万行的表 B+ 树只有 3 层&quot;，并说清计算过程</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出 B+ 树相比 B 树的三个优势（数据下沉、叶子链表、IO 稳定）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出为什么不用红黑树（树高）和哈希（范围查询）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释聚簇索引和二级索引的区别，以及&quot;回表&quot;是什么</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能用&quot;索引覆盖&quot;举一个具体例子（写出索引和 SQL）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能默写最左前缀原则的 5 种查询场景，并解释&quot;范围查询后列失效&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能说出至少 4 种索引失效的原因，并给出正确写法</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 能说出&quot;什么时候不该建索引&quot;（至少 3 种）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="8"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,63)])])}const b=t(l,[["render",o]]);export{u as __pageData,b as default};
